import data from "./registry.json";
import { PY_MODES, PY_QUESTION_FORMATS, PY_STATUSES, datasetIdOf, type PyItemStatus, type PyRegistry } from "./types";

/** The canonical registry (plan §3). Generated by scripts/python-v2/import-catalog.mjs; statuses are edited in place. */
export const pyRegistry = data as PyRegistry;

const rank = (s: PyItemStatus) => PY_STATUSES.indexOf(s);

/** Every entry that has a status, mode, prerequisites and datasets, in course order. */
export function trackedItems(reg: PyRegistry = pyRegistry) {
  return [
    ...reg.lessons.map((e) => ({ kind: "lesson" as const, ...e })),
    ...reg.questions.map((e) => ({ kind: "question" as const, ...e })),
    ...reg.projects.flatMap((p) => p.milestones.map((e) => ({ kind: "milestone" as const, ...e }))),
  ];
}

/**
 * Structural problems in the registry. Empty means valid.
 * `available` lists datasets with a built manifest; published content may only use those.
 */
export function validateRegistry(reg: PyRegistry, available: ReadonlySet<string> = new Set()): string[] {
  const problems: string[] = [];
  const seen = new Set<string>();
  const add = (id: string) => (seen.has(id) ? problems.push(`duplicate id ${id}`) : seen.add(id));
  reg.modules.forEach((m) => add(m.id));
  reg.projects.forEach((p) => add(p.id));
  reg.tools.forEach((t) => add(t.id));
  const items = trackedItems(reg);
  items.forEach((e) => add(e.id));

  const datasets = new Map(reg.datasets.map((d) => [d.id, d]));
  const order = new Map<string, number>(reg.lessons.map((l, i) => [l.id, i]));
  const statusOf = new Map<string, PyItemStatus>(items.map((e) => [e.id, e.status]));
  const modules = new Set(reg.modules.map((m) => m.id));

  for (const m of reg.modules) {
    if (!m.lessons.length) problems.push(`${m.id}: no lessons`);
    for (const l of m.lessons) if (reg.lessons.find((x) => x.id === l)?.module !== m.id) problems.push(`${m.id}: lesson ${l} is not in this module`);
  }
  for (const e of items) {
    if (!PY_STATUSES.includes(e.status)) problems.push(`${e.id}: unknown status ${e.status}`);
    if (!PY_MODES.includes(e.mode)) problems.push(`${e.id}: unknown mode ${e.mode}`);
    if ("module" in e && !modules.has(e.module)) problems.push(`${e.id}: unknown module ${e.module}`);
    if (e.kind === "question" && !PY_QUESTION_FORMATS.includes(e.format)) problems.push(`${e.id}: unknown format ${e.format}`);
    if (!e.datasets.length) problems.push(`${e.id}: no dataset`);
    for (const p of e.prerequisites) {
      if (!statusOf.has(p)) problems.push(`${e.id}: unknown prerequisite ${p}`);
      else if (e.kind === "lesson" && (order.get(p) ?? Infinity) >= order.get(e.id)!) problems.push(`${e.id}: prerequisite ${p} comes later`);
      else if (e.status === "published" && statusOf.get(p) !== "published") problems.push(`${e.id}: published before its prerequisite ${p}`);
    }
    for (const ref of e.datasets) {
      const d = datasets.get(datasetIdOf(ref));
      if (!d) problems.push(`${e.id}: unknown dataset ${ref}`);
      else if (d.licence.status === "replaced") problems.push(`${e.id}: uses ${d.id}, which is replaced by ${d.replacedBy}`);
      else if (rank(e.status) >= rank("reviewed")) {
        // Reviewed or published content must run on data we can ship.
        if (d.licence.status === "review") problems.push(`${e.id}: ${e.status} but ${d.id}'s licence isn't cleared`);
        if (d.kind !== "inline" && !available.has(d.id)) problems.push(`${e.id}: ${e.status} but ${d.id} has no built editions`);
      }
    }
  }
  for (const p of reg.projects) {
    if (!modules.has(p.unlockAfter)) problems.push(`${p.id}: unknown unlock module ${p.unlockAfter}`);
    if (p.milestones.length < 5 || p.milestones.length > 7) problems.push(`${p.id}: ${p.milestones.length} milestones (plan: 5–7)`);
  }
  return problems;
}

type Count = Record<string, number>;
const bump = (c: Count, k: string) => void (c[k] = (c[k] ?? 0) + 1);

/** Dataset-to-content coverage (plan §3): who uses each dataset, what's unused, and what can't ship yet. */
export function coverageReport(reg: PyRegistry, available: ReadonlySet<string> = new Set()) {
  const items = trackedItems(reg);
  const projectsByDataset: Record<string, string[]> = {};
  for (const p of reg.projects) for (const ref of p.datasets) (projectsByDataset[datasetIdOf(ref)] ??= []).push(p.id);
  const datasets = reg.datasets.map((d) => {
    const users = items.filter((e) => e.datasets.some((r) => datasetIdOf(r) === d.id));
    return {
      id: d.id,
      title: d.title,
      licence: d.licence.status,
      built: d.kind === "inline" || available.has(d.id),
      lessons: users.filter((e) => e.kind === "lesson").length,
      questions: users.filter((e) => e.kind === "question").length,
      projects: projectsByDataset[d.id] ?? [],
      modules: [...new Set(users.flatMap((e) => ("module" in e ? [e.module] : [])))],
    };
  });
  const blocked = items
    .flatMap((e) =>
      e.datasets.flatMap((ref) => {
        const d = reg.datasets.find((x) => x.id === datasetIdOf(ref));
        if (!d) return [{ id: e.id, dataset: ref, reason: "unknown dataset" }];
        if (d.licence.status === "replaced") return [{ id: e.id, dataset: d.id, reason: `replaced by ${d.replacedBy}` }];
        if (d.licence.status === "review") return [{ id: e.id, dataset: d.id, reason: "licence not cleared" }];
        if (d.kind !== "inline" && !available.has(d.id)) return [{ id: e.id, dataset: d.id, reason: "no built editions" }];
        return [];
      }),
    );
  const byStatus: Count = {}, byMode: Count = {}, byFormat: Count = {}, byStage: Count = {};
  const stageOf = new Map(reg.modules.map((m) => [m.id, m.stage]));
  for (const e of items) {
    bump(byStatus, `${e.kind}:${e.status}`);
    bump(byMode, `${e.kind}:${e.mode}`);
    if (e.kind === "question") bump(byFormat, e.format);
    if ("module" in e) bump(byStage, `stage ${stageOf.get(e.module)} ${e.kind}s`);
  }
  return {
    datasets,
    unused: datasets.filter((d) => !d.lessons && !d.questions && !d.projects.length && reg.datasets.find((x) => x.id === d.id)!.licence.status !== "replaced").map((d) => d.id),
    blocked,
    byStatus,
    byMode,
    byFormat,
    byStage,
  };
}
